constant WIDE_TOOL: str = "/* The wide world, for defect 238's cases (panel 191's R3). Every name, value
 * and command line is made, passed and read through the wide API, so no code
 * page of a launcher touches it. Every argument is ASCII: `\uXXXX` is a UTF-16
 * unit, `\n` a line end, `\\` a backslash; every answer is ASCII the same way,
 * a byte of a file's contents above ASCII as `\xHH`.
 *   mk <path> <text>          a file by a wide name, holding <text> as UTF-8
 *   mkdir <path>
 *   cp <from> <to>
 *   ls <dir>                  its names by FindFirstFileW, one a line
 *   cat <path>                its bytes, or `absent`
 *   abs <path>                its absolute path
 *   symlink <name> <target>   a symbolic link to a file
 *   attrs <path>              `a link`, `a directory`, `a plain file`, `absent`
 *   run <cwd|-> <NAME=VALUE|NAME=|-> <out> <err> <program> <args...>
 *                             started by CreateProcessW, the program and the
 *                             folder made absolute first, `NAME=` removing the
 *                             variable; answers `exit N`
 *   runraw <out> <err> <program> <line>   the command line handed over as is
 * Exit 0, or 1 with the reason on stdout. */
#include <fcntl.h>
#include <io.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <wchar.h>
#include <windows.h>

static wchar_t *wide(const char *s) {
    size_t n = strlen(s);
    wchar_t *w = calloc(n + 1, sizeof *w);
    size_t at = 0;
    for (size_t i = 0; i < n;) {
        if (s[i] == '\\' && i + 6 <= n && s[i + 1] == 'u') {
            char hex[5] = {s[i + 2], s[i + 3], s[i + 4], s[i + 5], 0};
            w[at++] = (wchar_t)strtoul(hex, NULL, 16);
            i += 6;
        } else if (s[i] == '\\' && s[i + 1] == 'n') {
            w[at++] = L'\n';
            i += 2;
        } else if (s[i] == '\\' && s[i + 1] == '\\') {
            w[at++] = L'\\';
            i += 2;
        } else {
            w[at++] = (wchar_t)(unsigned char)s[i];
            i += 1;
        }
    }
    w[at] = 0;
    return w;
}

static void say_wide(const wchar_t *w) {
    for (; *w != 0; w++) {
        if (*w >= 0x20 && *w < 0x7F && *w != L'\\') putchar((int)*w);
        else if (*w == L'\\') fputs("\\\\", stdout);
        else printf("\\u%04x", (unsigned)*w);
    }
}

static wchar_t *absolute(const wchar_t *path) {
    DWORD room = GetFullPathNameW(path, 0, NULL, NULL);
    if (room == 0) return NULL;
    wchar_t *out = calloc(room, sizeof *out);
    if (GetFullPathNameW(path, room, out, NULL) == 0) return NULL;
    return out;
}

/* One word of a command line as the C runtime reads it back: quoted where it
 * holds a space, a tab or a quote or is empty, a quote inside escaped, and the
 * backslashes before a quote doubled. */
static void quoted(wchar_t *line, size_t *at, const wchar_t *word) {
    int needs = word[0] == 0 || wcspbrk(word, L" \t\"") != NULL;
    if (!needs) {
        for (const wchar_t *p = word; *p != 0; p++) line[(*at)++] = *p;
        return;
    }
    line[(*at)++] = L'"';
    for (const wchar_t *p = word;;) {
        size_t slashes = 0;
        while (*p == L'\\') { slashes += 1; p++; }
        if (*p == 0) {
            for (size_t k = 0; k < slashes * 2; k++) line[(*at)++] = L'\\';
            break;
        }
        if (*p == L'"') {
            for (size_t k = 0; k < slashes * 2 + 1; k++) line[(*at)++] = L'\\';
        } else {
            for (size_t k = 0; k < slashes; k++) line[(*at)++] = L'\\';
        }
        line[(*at)++] = *p;
        p++;
    }
    line[(*at)++] = L'"';
}

static int started(wchar_t *program, wchar_t *line, wchar_t *cwd, const char *out_path, const char *err_path) {
    SECURITY_ATTRIBUTES sa = {sizeof sa, NULL, TRUE};
    HANDLE out = CreateFileW(wide(out_path), GENERIC_WRITE, FILE_SHARE_READ, &sa, CREATE_ALWAYS, 0, NULL);
    HANDLE err = CreateFileW(wide(err_path), GENERIC_WRITE, FILE_SHARE_READ, &sa, CREATE_ALWAYS, 0, NULL);
    HANDLE nul = CreateFileW(L"NUL", GENERIC_READ, FILE_SHARE_READ, &sa, OPEN_EXISTING, 0, NULL);
    if (out == INVALID_HANDLE_VALUE || err == INVALID_HANDLE_VALUE || nul == INVALID_HANDLE_VALUE) {
        printf("streams failed %lu\n", GetLastError());
        return 1;
    }
    STARTUPINFOW si;
    memset(&si, 0, sizeof si);
    si.cb = sizeof si;
    si.dwFlags = STARTF_USESTDHANDLES;
    si.hStdInput = nul;
    si.hStdOutput = out;
    si.hStdError = err;
    PROCESS_INFORMATION pi;
    if (!CreateProcessW(program, line, NULL, NULL, TRUE, 0, NULL, cwd, &si, &pi)) {
        printf("run failed %lu\n", GetLastError());
        return 1;
    }
    WaitForSingleObject(pi.hProcess, INFINITE);
    DWORD code = 0;
    GetExitCodeProcess(pi.hProcess, &code);
    CloseHandle(pi.hThread);
    CloseHandle(pi.hProcess);
    CloseHandle(out);
    CloseHandle(err);
    CloseHandle(nul);
    printf("exit %lu\n", code);
    return 0;
}

int main(int argc, char **argv) {
    _setmode(_fileno(stdout), _O_BINARY);
    if (argc < 2) return 64;
    const char *verb = argv[1];
    if (!strcmp(verb, "mk") && argc == 4) {
        wchar_t *text = wide(argv[3]);
        int bytes = WideCharToMultiByte(CP_UTF8, 0, text, -1, NULL, 0, NULL, NULL);
        char *utf8 = calloc((size_t)bytes + 1, 1);
        WideCharToMultiByte(CP_UTF8, 0, text, -1, utf8, bytes, NULL, NULL);
        HANDLE h = CreateFileW(wide(argv[2]), GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL);
        if (h == INVALID_HANDLE_VALUE) { printf("mk failed %lu\n", GetLastError()); return 1; }
        DWORD put = 0;
        DWORD want = (DWORD)strlen(utf8);
        BOOL wrote = WriteFile(h, utf8, want, &put, NULL);
        CloseHandle(h);
        if (!wrote || put != want) { printf("mk failed to write\n"); return 1; }
        return 0;
    }
    if (!strcmp(verb, "mkdir") && argc == 3) {
        if (!CreateDirectoryW(wide(argv[2]), NULL) && GetLastError() != ERROR_ALREADY_EXISTS) {
            printf("mkdir failed %lu\n", GetLastError());
            return 1;
        }
        return 0;
    }
    if (!strcmp(verb, "cp") && argc == 4) {
        if (!CopyFileW(wide(argv[2]), wide(argv[3]), FALSE)) { printf("cp failed %lu\n", GetLastError()); return 1; }
        return 0;
    }
    if (!strcmp(verb, "ls") && argc == 3) {
        wchar_t *dir = wide(argv[2]);
        size_t n = wcslen(dir);
        wchar_t *pattern = calloc(n + 3, sizeof *pattern);
        wcscpy(pattern, dir);
        wcscat(pattern, L"\\*");
        WIN32_FIND_DATAW d;
        HANDLE h = FindFirstFileW(pattern, &d);
        if (h == INVALID_HANDLE_VALUE) { printf("ls failed %lu\n", GetLastError()); return 1; }
        do {
            if (!wcscmp(d.cFileName, L".") || !wcscmp(d.cFileName, L"..")) continue;
            say_wide(d.cFileName);
            putchar('\n');
        } while (FindNextFileW(h, &d));
        FindClose(h);
        return 0;
    }
    if (!strcmp(verb, "cat") && argc == 3) {
        HANDLE h = CreateFileW(wide(argv[2]), GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL);
        if (h == INVALID_HANDLE_VALUE) { printf("absent"); return 0; }
        unsigned char buf[4096];
        DWORD got = 0;
        while (ReadFile(h, buf, sizeof buf, &got, NULL) && got > 0) {
            for (DWORD i = 0; i < got; i++) {
                unsigned char b = buf[i];
                if (b == '\n') fputs("\\n", stdout);
                else if (b == '\\') fputs("\\\\", stdout);
                else if (b >= 0x20 && b < 0x7F) putchar(b);
                else printf("\\x%02x", b);
            }
        }
        CloseHandle(h);
        return 0;
    }
    if (!strcmp(verb, "abs") && argc == 3) {
        wchar_t *full = absolute(wide(argv[2]));
        if (full == NULL) { printf("abs failed %lu\n", GetLastError()); return 1; }
        say_wide(full);
        return 0;
    }
    if (!strcmp(verb, "symlink") && argc == 4) {
        if (!CreateSymbolicLinkW(wide(argv[2]), wide(argv[3]), SYMBOLIC_LINK_FLAG_ALLOW_UNPRIVILEGED_CREATE)) {
            printf("symlink failed %lu\n", GetLastError());
            return 1;
        }
        return 0;
    }
    if (!strcmp(verb, "attrs") && argc == 3) {
        DWORD a = GetFileAttributesW(wide(argv[2]));
        if (a == INVALID_FILE_ATTRIBUTES) printf("absent");
        else if (a & FILE_ATTRIBUTE_REPARSE_POINT) printf("a link");
        else if (a & FILE_ATTRIBUTE_DIRECTORY) printf("a directory");
        else printf("a plain file");
        return 0;
    }
    if (!strcmp(verb, "run") && argc >= 7) {
        wchar_t *cwd = strcmp(argv[2], "-") ? absolute(wide(argv[2])) : NULL;
        if (strcmp(argv[3], "-")) {
            wchar_t *pair = wide(argv[3]);
            wchar_t *eq = wcschr(pair, L'=');
            if (eq == NULL) return 66;
            *eq = 0;
            SetEnvironmentVariableW(pair, eq[1] != 0 ? eq + 1 : NULL);
        }
        wchar_t *program = absolute(wide(argv[6]));
        if (program == NULL) { printf("abs failed %lu\n", GetLastError()); return 1; }
        size_t room = 16 + 2 * wcslen(program) + 3;
        for (int i = 7; i < argc; i++) room += 2 * strlen(argv[i]) + 3;
        wchar_t *line = calloc(room, sizeof *line);
        size_t at = 0;
        quoted(line, &at, program);
        for (int i = 7; i < argc; i++) {
            line[at++] = L' ';
            quoted(line, &at, wide(argv[i]));
        }
        line[at] = 0;
        return started(program, line, cwd, argv[4], argv[5]);
    }
    if (!strcmp(verb, "runraw") && argc == 6) {
        wchar_t *program = absolute(wide(argv[4]));
        if (program == NULL) { printf("abs failed %lu\n", GetLastError()); return 1; }
        return started(program, wide(argv[5]), NULL, argv[2], argv[3]);
    }
    return 64;
}
"

